-- Create "galleries" table
CREATE TABLE `galleries` (`id` int unsigned NOT NULL AUTO_INCREMENT, `preview_small_style` varchar(64) NOT NULL DEFAULT 'gallery_thumbnail', `preview_medium_style` varchar(64) NOT NULL DEFAULT 'gallery_medium', `title` varchar(255) NULL, `description` text NULL, `weight` int NULL DEFAULT 0, `status` bool NULL DEFAULT true, `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `updated_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), INDEX `gallery_status` (`status`), INDEX `gallery_nid_status_weight` (`nid`, `status`, `weight`), CONSTRAINT `galleries_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "gallery_content_types" table
CREATE TABLE `gallery_content_types` (`id` int unsigned NOT NULL AUTO_INCREMENT, `default_enabled` bool NOT NULL DEFAULT false, `picture_field` varchar(64) NOT NULL DEFAULT '', `content_type_id` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `gallerycontenttype_content_type_id` (`content_type_id`), CONSTRAINT `gallery_content_types_content_types_content_type` FOREIGN KEY (`content_type_id`) REFERENCES `content_types` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "gallery_items" table
CREATE TABLE `gallery_items` (`id` int unsigned NOT NULL AUTO_INCREMENT, `title` varchar(255) NULL, `description` text NULL, `weight` int NULL DEFAULT 0, `is_cover` bool NOT NULL DEFAULT false, `created_at` timestamp NOT NULL DEFAULT (CURRENT_TIMESTAMP), `gallery_id` int unsigned NOT NULL, `fid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `galleryitem_gallery_id_fid` (`gallery_id`, `fid`), INDEX `galleryitem_gallery_id_weight` (`gallery_id`, `weight`), INDEX `galleryitem_gallery_id_is_cover` (`gallery_id`, `is_cover`), INDEX `galleryitem_fid` (`fid`), CONSTRAINT `gallery_items_galleries_gallery` FOREIGN KEY (`gallery_id`) REFERENCES `galleries` (`id`) ON DELETE CASCADE, CONSTRAINT `gallery_items_files_file` FOREIGN KEY (`fid`) REFERENCES `files` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
-- Create "gallery_nodes" table
CREATE TABLE `gallery_nodes` (`id` int unsigned NOT NULL AUTO_INCREMENT, `nid` int unsigned NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `gallerynode_nid` (`nid`), CONSTRAINT `gallery_nodes_nodes_node` FOREIGN KEY (`nid`) REFERENCES `nodes` (`id`) ON DELETE CASCADE) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci;
